 function findText(n){if(n.tipo==='texto'&&n.texto)return n;for(const child of n.hijos||[]){const result=findText(child);if(result)return result;}return null;}
 function renderActions(target,n){const row=el('div','ds-node-actions');button(row,'↑',()=>sibling(-1),'ds-button');button(row,'↓',()=>sibling(1),'ds-button');button(row,'Copiar',copyObjects,'ds-button');button(row,'Pegar',pasteObjects,'ds-button');button(row,'Duplicar',duplicate,'ds-button');button(row,'Quitar',remove,'ds-button ds-danger');target.append(row);}
 function sibling(direction){const item=current();if(!item)return;mutate(()=>{const list=item.list,index=list.indexOf(item.node),to=Math.max(0,Math.min(list.length-1,index+direction));list.splice(index,1);list.splice(to,0,item.node);});}
 function duplicate(){if(!selected.length)return;const entries=map(),items=selected.map(id=>entries.get(id)?.node).filter(Boolean),extra=items.reduce((sum,n)=>sum+M.contar(n)-(n.tipo==='seccion'?1:0),0);if(!safeCount(extra)||state.diseno.bloques.length+items.filter(n=>n.tipo==='seccion').length>60){toast('Duplicar esta selección supera el límite de la página.',true);return;}mutate(()=>{const ids=[];for(const id of selected){const n=M.duplicar(state.diseno,id);if(n)ids.push(n.id);}selected=ids;},{reveal:true});}
 function copyObjects(){if(busy||!state||!selected.length)return;objectClipboard=M.copiar(state.diseno,selected);lastPaste=[];pasteTarget=null;pasteCount=0;toast(objectClipboard.length+' objeto'+(objectClipboard.length===1?' copiado.':'s copiados.')+' Usa Ctrl/⌘ V para pegar en este diseñador.');}
 function pasteObjects(){if(busy||!state)return;if(!objectClipboard.length){toast('Primero selecciona y copia un objeto del diseñador.',true);return;}const original=objectClipboard.map(i=>i.node.id),repeated=selected.length&&selected.every(id=>lastPaste.includes(id)),same=selected.length&&selected.every(id=>original.includes(id));const target=repeated?pasteTarget:same?null:destination()?.node.id||null;const offset=(repeated?pasteCount+1:1)*16;let result;mutate(()=>{result=M.pegar(state.diseno,objectClipboard,{parentId:target,offset});if(!result.error){selected=result.ids;lastPaste=[...result.ids];pasteTarget=target;pasteCount=repeated?pasteCount+1:1;for(const id of selected)for(const parent of map().get(id)?.ancestros||[])expanded.add(parent);}},{reveal:true});if(result.error){toast(result.error,true);return;}rightTab('propiedades');renderProperties();toast('Copia agregada. Puedes moverla o recuperarla con Deshacer.');}
 async function remove(){if(!selected.length)return;const count=selected.length;if(!await confirm('¿Quitar '+(count>1?count+' objetos':'este elemento')+'?','Se quitará de la edición. Puedes recuperarlo con Deshacer; las revisiones guardadas se conservan.','Quitar'))return;mutate(()=>{M.quitar(state.diseno,selected);selected=[];});}
 function historyStep(delta){if(busy)return;clearTimeout(textTimer);const next=cursor+delta;if(next<0||next>=history.length)return;cursor=next;Object.assign(state,JSON.parse(history[cursor]));selected=selected.filter(id=>map().has(id));renderTree();renderProperties();render();status();persist();}
 function confirm(title,text,label='Confirmar'){if(dialogResolve)return Promise.resolve(false);$('ds-dialog-title').textContent=title;$('ds-dialog-text').textContent=text;$('ds-dialog-ok').textContent=label;$('ds-dialog').showModal();$('ds-dialog-cancel').focus();return new Promise(resolve=>dialogResolve=resolve);}
 function settle(value){$('ds-dialog').close();const resolve=dialogResolve;dialogResolve=null;resolve?.(value);}
 $('ds-dialog-cancel').addEventListener('click',()=>settle(false));$('ds-dialog-ok').addEventListener('click',()=>settle(true));$('ds-dialog').addEventListener('cancel',e=>{e.preventDefault();settle(false);});
 async function request(path,{method='GET',body=null}={}){const headers={Accept:'application/json'};if(method!=='GET'){const r=await fetch('/sesion/estado',{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!r.ok||r.redirected)throw new Error('Tu sesión venció. La edición se conserva en este navegador; inicia sesión en otra pestaña y vuelve a intentar.');const tokens=await r.json();if(tokens.csrfToken)headers[tokens.csrfCabecera||'X-CSRF-TOKEN']=tokens.csrfToken;}if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch('/admin/diseno-web/visual'+path,{method,headers,credentials:'same-origin',cache:'no-store',body:body?(body instanceof FormData?body:JSON.stringify(body)):null});if(res.redirected)throw new Error('Tu sesión cambió. Inicia sesión en otra pestaña para conservar esta edición.');if(!res.ok){let message=res.status===403?'No tienes permiso para esta acción.':'No se pudo completar la operación. La edición se conserva.';try{message=(await res.json()).mensaje||message;}catch(_){}throw new Error(message);}return res.json();}
 function canonical(form){const copy=M.clone(form);copy.nombre=copy.nombre||'Tu escuela';copy.eslogan=copy.eslogan||'SEMBRANDO PRINCIPIOS, TRANSFORMANDO CULTURA.';copy.principal=copy.principal||'#2b5031';copy.acento=copy.acento||'#ffc83e';copy.extras??={albumes:[],ubicaciones:[],contacto:{}};copy.diseno=M.convertir(copy);return copy;}
 function install(form,{clean=false,label='Borrador',remember=true}={}){state=canonical(form);origin=label;selected=[];expanded.clear();if(clean)saved=JSON.stringify(pack());if(remember)push();renderTree();renderProperties();renderMedia();renderRevisions();status();render();}
 async function save(){if(!state||busy)return;const invalid=$('ds-properties').querySelector('input:invalid,select:invalid,textarea:invalid');if(invalid){invalid.reportValidity();invalid.focus();return;}clearTimeout(textTimer);push();if(!await confirm('¿Guardar el borrador?',state.diseno.bloques.length+' secciones y '+(map().size-state.diseno.bloques.length)+' componentes. Se creará una nueva revisión; la página pública cambiará sólo al publicar.','Guardar borrador'))return;busy=true;workspace.inert=true;status();try{data=await request('/datos',{method:'POST',body:{...pack(),version:data.sitio.version}});state=canonical(data.sitio);saved=serial();origin='Borrador · Revisión '+data.sitio.version;clearTimeout(cacheTimer);try{localStorage.removeItem(cacheKey);}catch(_){}renderRevisions();renderMedia();renderTree();renderProperties();render();toast('Borrador guardado. Revisa la vista previa antes de publicar.');$('ds-alert').hidden=true;}catch(e){error(e.message);}finally{busy=false;workspace.inert=false;status();}}
 async function publish(){if(busy||!state)return;if(!data.puedePublicar){toast('Necesitas el permiso Diseño web - Publicar.',true);return;}if(dirty()){toast('Guarda el borrador antes de publicar esta edición.',true);return;}if(!await confirm('¿Publicar la revisión '+data.sitio.version+'?','Se publicará en '+(data.publicacionUrl||('/sitio/'+data.codigo))+'. '+(data.inicioVinculado?'También se verá en la página principal de esta instalación.':'La página principal de la instalación conserva su configuración actual.')+' Puedes cancelar para revisar primero.','Publicar versión'))return;busy=true;workspace.inert=true;status();try{await request('/publicar',{method:'POST',body:{version:data.sitio.version}});data.publicadaVersion=data.sitio.version;toast('Versión publicada. Puedes abrirla desde Publicaciones e historial.');}catch(e){error(e.message);}finally{busy=false;workspace.inert=false;status();}}
 async function loadPublic(initial=false){if(!initial&&!await confirm('¿Cargar la página publicada?','Reemplazará los cambios locales sin guardar. Los borradores guardados y la publicación actual se conservan.','Cargar para editar'))return;const result=await request('/publicada');let source;if(result.sitio){source=M.clone(result.sitio);if(!source.diseno&&window.NexoVisual?.desdePublicada)source.diseno=window.NexoVisual.desdePublicada(source);}else{source={...M.clone(data.sitio),extras:{albumes:[],ubicaciones:[],contacto:{}},diseno:M.original({}),principal:'#2b5031',acento:'#ffc83e'};}install(source,{label:result.original?'Página escolar publicada · edición local':'Publicación · Revisión '+result.sitio.version,remember:!initial});if(initial)toast('Abrimos la página publicada completa. Tu borrador anterior sigue disponible en Versiones.');}
