 function renderRevisions(){const target=$('ds-revisions');target.replaceChildren(el('h2','','Revisiones guardadas'));for(const r of data.revisiones||[]){const card=el('article','ds-version');card.append(el('strong','','Revisión '+r.version));const when=r.guardado_en?new Date(r.guardado_en).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}):'';if(when)card.append(el('small','',when));const actions=el('div','ds-actions'),view=el('a','ds-button','Ver ↗');view.href='/admin/diseno-web/vista-previa?revision='+r.version;view.target='_blank';view.rel='noopener';actions.append(view);button(actions,'Restaurar',async()=>{if(busy||!await confirm('¿Restaurar la revisión '+r.version+'?','Se creará un nuevo borrador con esa copia completa. Los cambios locales sin guardar se descartarán; la página pública se conserva.','Restaurar como borrador'))return;busy=true;workspace.inert=true;status();try{data=await request('/restaurar',{method:'POST',body:{revision:Number(r.version),version:data.sitio.version}});install(data.sitio,{clean:data.sitio.diseno?.bloques.every(b=>b.tipo==='seccion'),label:'Borrador restaurado · Revisión '+data.sitio.version});history=[serial()];cursor=0;toast('Revisión restaurada. Revisa el diseño antes de publicar.');}catch(e){error(e.message);}finally{busy=false;workspace.inert=false;status();}});card.append(actions);target.append(card);}if(!(data.revisiones||[]).length)target.append(el('p','ds-hint','Tus revisiones aparecerán después del primer guardado.'));button(target,'Ver publicaciones',()=>library.open('publicaciones'),'ds-button ds-full');button(target,'Publicar revisión guardada',publish,'ds-button ds-full');}
