 function validCache(value){if(!value||!Array.isArray(value.diseno?.bloques)||value.diseno.bloques.length>60||!value.diseno.bloques.length)return false;const stack=value.diseno.bloques.map(b=>({list:b.componentes,depth:0}));let count=0;while(stack.length){const {list,depth}=stack.pop();if(!Array.isArray(list)||depth>12)return false;for(const n of list){if(++count>800||!n||!Array.isArray(n.hijos)||!/^[a-zA-Z0-9-]{1,60}$/.test(n.id||''))return false;stack.push({list:n.hijos,depth:depth+1});}}return true;}
